def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_tight = (supply <= 17)
    supply_loose = (supply >= 22)

    if hp <= 2 or no_water_days >= 2:
        bid = max(78.0, highest_prev + 4.0)
    elif hp <= 4 or no_water_days >= 1:
        if supply_tight:
            bid = max(68.0, highest_prev * 0.78 + 3.0)
        else:
            bid = max(58.0, avg_prev * 0.62 + 2.0)
    else:
        if supply_loose:
            bid = 16.0 + 2.0 * rich_opp
        elif supply_tight:
            if highest_prev >= 110:
                bid = 28.0
            else:
                bid = max(32.0, avg_prev * 0.42)
        else:
            if urgent_opp >= 2:
                bid = max(36.0, avg_prev * 0.45)
            elif highest_prev >= 120:
                bid = 24.0
            elif highest_prev >= 90:
                bid = 30.0
            else:
                bid = max(26.0, avg_prev * 0.38 + 1.0)

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid *= 0.9
        else:
            bid *= 1.08

    reserve = 0.0
    if hp <= 4:
        reserve = DAILY_SALARY * 0.6
    elif hp <= 2:
        reserve = DAILY_SALARY * 0.3

    max_spend = max(0.0, budget - reserve)
    if max_spend <= 0:
        max_spend = budget

    bid = min(bid, max_spend)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday immediate behavior from previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate how many water units are likely needed/available this round
    # (We only use it to scale our bid; actual allocation depends on game rules.)
    supply_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Pressure-based adjustment: if we are already on low hp or have had no water recently, bid more.
    low_hp = my_hp <= 2.5
    critical_no_water = my_no_water_days >= 2

    # If someone yesterday bid extremely high, assume they were trying to secure survival.
    # We counter with a moderate-to-strong bid, but not full send unless we are critical.
    extreme_threshold = DAILY_SALARY * 0.85  # 76.5

    if highest_prev_bid >= extreme_threshold:
        if low_hp or critical_no_water:
            bid = DAILY_SALARY * 0.95
        else:
            # Shade above the likely second-best pressure to avoid losing to the extreme bidder.
            bid = max(DAILY_SALARY * 0.6, second_prev_bid + 2.0)
    else:
        # If no one was extremely aggressive, keep bid moderate to win at lower price.
        # Use supply_units to slightly reduce bid when supply is high.
        # supply_units near 1.0 => tight; near 2.7 => ample.
        tightness = 1.0
        if supply_units > 0:
            tightness = max(0.6, min(1.2, 1.6 / supply_units))
        bid = DAILY_SALARY * 0.52 * tightness

        if low_hp or critical_no_water:
            bid = max(bid, DAILY_SALARY * 0.75)

    # Final safety caps
    bid = float(bid)
    if my_budget <= 0:
        return 0.0

    # Ensure we don't exceed budget; also keep bids within a reasonable upper bound.
    upper = min(my_budget, DAILY_SALARY * 1.2)
    bid = min(max(0.0, bid), upper)

    # Tiny day-based dithering to avoid exact ties (still deterministic-ish)
    # (day may be int; use it safely)
    try:
        day_int = int(day)
    except Exception:
        day_int = 0
    if day_int % 3 == 1:
        bid *= 1.01
    elif day_int % 3 == 2:
        bid *= 0.99

    bid = min(max(0.0, bid), upper)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine target bid based on health and water needs
    if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
        target = max(DAILY_SALARY * 0.95, max_prev_bid + 1.5)
    else:
        target = max(DAILY_SALARY * 0.6, max_prev_bid + 0.5)

    return min(my_status['budget'], target)
